# How a String in a multibyte encoding is walked, generated by
# tools/cjk.rb from ruby's own tables. Where a lead byte's character
# ends, and which bytes may sit at each place inside it: that is all
# the runtime needs to find one character after another.

# Whether the encoding `index` names holds characters that span bytes
# in a way of its own: not UTF-8, not UTF-16 or UTF-32, and not one
# byte one character.
sig [Word] => Bool
machine def zr_enc_mb_p(index)
  index >= 10 && index <= 21 || index == 39 || index >= 76 && index <= 77 || index >= 79 && index <= 84 || index == 93 || index == 96 || index == 98 || index == 100 || index == 102
end

# Whether the encoding writes its characters as UTF-8 writes them.
sig [Word] => Bool
machine def zr_enc_utf8_like_p(index)
  index == 9 || index == 95 || index == 97 || index == 101
end

# How many bytes the character that starts with `lead` holds, 1 for a
# byte that stands alone and 0 for one that starts no character at
# all. `second` is the byte after it, or 0 at the end of the text.
sig [Word, Word, Word] => Word
machine def zr_mb_lead_len(index, lead, second)
  # EUC-JP
  if index == 10
    if lead >= 128 && lead <= 141 || lead >= 144 && lead <= 160 || lead == 255
      return 0
    end
    if lead == 143
      return 3
    end
    if lead == 142 || lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # Windows-31J
  if index == 11
    if lead == 128 || lead == 160 || lead >= 253 && lead <= 255
      return 0
    end
    if lead >= 129 && lead <= 159 || lead >= 224 && lead <= 252
      return 2
    end
    return 1
  end
  # Big5
  if index == 12
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # Big5-HKSCS
  if index == 13
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # Big5-UAO
  if index == 14
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # CESU-8
  if index == 15
    if lead >= 128 && lead <= 193 || lead >= 240 && lead <= 255
      return 0
    end
    if lead >= 224 && lead <= 239
      return 3
    end
    if lead >= 194 && lead <= 223
      return 2
    end
    return 1
  end
  # CP949
  if index == 16
    if lead == 255
      return 0
    end
    if lead >= 129 && lead <= 254
      return 2
    end
    return 1
  end
  # Emacs-Mule
  if index == 17
    if lead == 128 || lead >= 158 && lead <= 255
      return 0
    end
    if lead >= 156 && lead <= 157
      return 4
    end
    if lead >= 144 && lead <= 155
      return 3
    end
    if lead >= 129 && lead <= 143
      return 2
    end
    return 1
  end
  # EUC-KR
  if index == 18
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # EUC-TW
  if index == 19
    if lead >= 128 && lead <= 141 || lead >= 143 && lead <= 160 || lead == 255
      return 0
    end
    if lead == 142
      return 4
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # GB18030
  if index == 20
    if lead == 128 || lead == 255
      return 0
    end
    if lead >= 129 && lead <= 254
      if second >= 48 && second <= 57
        return 4
      end
      if second >= 64 && second <= 126 || second >= 128 && second <= 254
        return 2
      end
      return 2
    end
    return 1
  end
  # GBK
  if index == 21
    if lead == 255
      return 0
    end
    if lead >= 129 && lead <= 254
      return 2
    end
    return 1
  end
  # Shift_JIS
  if index == 39
    if lead == 128 || lead == 160 || lead >= 253 && lead <= 255
      return 0
    end
    if lead >= 129 && lead <= 159 || lead >= 224 && lead <= 252
      return 2
    end
    return 1
  end
  # CP950
  if index == 76
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # CP951
  if index == 77
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # stateless-ISO-2022-JP
  if index == 79
    if lead == 128 || lead >= 158 && lead <= 255
      return 0
    end
    if lead >= 156 && lead <= 157
      return 4
    end
    if lead >= 144 && lead <= 155
      return 3
    end
    if lead >= 129 && lead <= 143
      return 2
    end
    return 1
  end
  # eucJP-ms
  if index == 80
    if lead >= 128 && lead <= 141 || lead >= 144 && lead <= 160 || lead == 255
      return 0
    end
    if lead == 143
      return 3
    end
    if lead == 142 || lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # CP51932
  if index == 81
    if lead >= 128 && lead <= 141 || lead >= 144 && lead <= 160 || lead == 255
      return 0
    end
    if lead == 143
      return 3
    end
    if lead == 142 || lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # EUC-JIS-2004
  if index == 82
    if lead >= 128 && lead <= 141 || lead >= 144 && lead <= 160 || lead == 255
      return 0
    end
    if lead == 143
      return 3
    end
    if lead == 142 || lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # GB2312
  if index == 83
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # GB12345
  if index == 84
    if lead >= 128 && lead <= 160 || lead == 255
      return 0
    end
    if lead >= 161 && lead <= 254
      return 2
    end
    return 1
  end
  # MacJapanese
  if index == 93
    if lead == 128 || lead == 160 || lead >= 253 && lead <= 255
      return 0
    end
    if lead >= 129 && lead <= 159 || lead >= 224 && lead <= 252
      return 2
    end
    return 1
  end
  # SJIS-DoCoMo
  if index == 96
    if lead == 128 || lead == 160 || lead >= 253 && lead <= 255
      return 0
    end
    if lead >= 129 && lead <= 159 || lead >= 224 && lead <= 252
      return 2
    end
    return 1
  end
  # SJIS-KDDI
  if index == 98
    if lead == 128 || lead == 160 || lead >= 253 && lead <= 255
      return 0
    end
    if lead >= 129 && lead <= 159 || lead >= 224 && lead <= 252
      return 2
    end
    return 1
  end
  # stateless-ISO-2022-JP-KDDI
  if index == 100
    if lead == 128 || lead >= 158 && lead <= 255
      return 0
    end
    if lead >= 156 && lead <= 157
      return 4
    end
    if lead >= 144 && lead <= 155
      return 3
    end
    if lead >= 129 && lead <= 143
      return 2
    end
    return 1
  end
  # SJIS-SoftBank
  if index == 102
    if lead == 128 || lead == 160 || lead >= 253 && lead <= 255
      return 0
