end

# Whether `byte` may sit at place `place` of a character that starts
# with `lead`.
sig [Word, Word, Word, Word] => Bool
machine def zr_mb_trail_ok(index, lead, place, byte)
  # EUC-JP
  if index == 10
    if place == 1 && (lead >= 142 && lead <= 143 || lead >= 161 && lead <= 254)
      return byte >= 161 && byte <= 254
    end
    if place == 2 && (lead == 143)
      return byte >= 161 && byte <= 254
    end
    return false
  end
  # Windows-31J
  if index == 11
    if place == 1 && (lead >= 129 && lead <= 159 || lead >= 224 && lead <= 252)
      return byte >= 64 && byte <= 126 || byte >= 128 && byte <= 252
