    return false
  end
  # CP949
  if index == 16
    if place == 1 && (lead >= 129 && lead <= 254)
      return byte >= 65 && byte <= 90 || byte >= 97 && byte <= 122 || byte >= 129 && byte <= 254
    end
    return false
  end
  # Emacs-Mule
  if index == 17
    if place == 1 && (lead >= 129 && lead <= 153)
