      return byte >= 161 && byte <= 176
    end
    if place == 1 && (lead >= 161 && lead <= 254)
      return byte >= 161 && byte <= 254
    end
    if place == 2 && (lead == 142)
      return byte >= 161 && byte <= 254
    end
    if place == 3 && (lead == 142)
      return byte >= 161 && byte <= 254
    end
    return false
  end
  # GB18030
  if index == 20
    if place == 1 && (lead >= 129 && lead <= 254)
      return byte >= 48 && byte <= 57 || byte >= 64 && byte <= 126 || byte >= 128 && byte <= 254
    end
    if place == 2 && (lead >= 129 && lead <= 254)
      return byte >= 129 && byte <= 254
    end
    if place == 3 && (lead >= 129 && lead <= 130)
      return byte >= 48 && byte <= 57
    end
    return false
  end
  # GBK
  if index == 21
    if place == 1 && (lead >= 129 && lead <= 254)
      return byte >= 64 && byte <= 126 || byte >= 128 && byte <= 254
    end
    return false
